<script setup lang="ts">
import {computed,onMounted,reactive,ref,watch} from "vue";import {useI18n} from "vue-i18n";import {useRouter} from "vue-router";import AdminLayout from "@/components/layout/AdminLayout.vue";import AppIcon from "@/components/AppIcon.vue";import AppFooter from "@/components/AppFooter.vue";import {api,type NotificationChannel,type NotificationRule,type WebhookConfig} from "@/api/client";import {useToast} from "@/composables/useToast";
const {t}=useI18n(),router=useRouter(),{notify}=useToast(),loading=ref(true),error=ref(""),tab=ref("channels"),channels=ref<NotificationChannel[]>([]),rules=ref<NotificationRule[]>([]),events=ref<any[]>([]),deliveries=ref<any[]>([]),catalog=ref<any[]>([]),cid=ref(""),rid=ref(""),busy=ref(false);
const config=():WebhookConfig=>({provider:"dingtalk",url:"",method:"POST",headers:"{}",body:"",dingTalkSecret:"",dingTalkMessageType:"text",testBody:'{"event":"{{event}}","status":"{{status}}","message":"{{message}}"}',messageTemplate:"{{event}}\\n{{status}}\\n{{message}}",testMessageTemplate:"PacPilot test"});
const ch=reactive({name:"",enabled:true,config:config()}),rule=reactive({name:"",enabled:true,eventType:"task.execution" as NotificationRule["eventType"],phase:"finished" as NotificationRule["phase"],outcome:"failure" as NotificationRule["outcome"],channelIds:[] as string[],subjectType:""});
watch(()=>rule.phase,(phase)=>{if(phase==="started"||phase==="progress")rule.outcome="any"});
const phases=computed(()=>catalog.value.find(x=>x.type===rule.eventType)?.phases??[]),outcomes=computed(()=>catalog.value.find(x=>x.type===rule.eventType)?.outcomes??[]),evName=(v:string)=>catalog.value.find(x=>x.type===v)?.label??v,phaseName=(v:string)=>({started:"开始时",finished:"结束时",state_changed:"状态变化时",progress:"执行中"} as Record<string,string>)[v]??v,outcomeName=(v?:string|null)=>({success:"成功",failure:"失败",cancelled:"取消",timeout:"超时",unknown:"未知",any:"任意"} as Record<string,string>)[v??"any"]??"不限制",cn=(id:string)=>channels.value.find(x=>x.id===id)?.name??id;
async function load(){loading.value=true;error.value="";try{if(!(await api.session()).loggedIn){await router.replace("/admin/login");return}const x=await api.notifications();channels.value=x.channels;rules.value=x.rules;events.value=[...x.events].reverse();deliveries.value=[...x.deliveries].reverse();catalog.value=x.eventCatalog}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=false}}
function resetC(){cid.value="";Object.assign(ch,{name:"",enabled:true,config:config()})}function editC(x:NotificationChannel){cid.value=x.id;Object.assign(ch,{name:x.name,enabled:x.enabled,config:{...x.config}})}
async function saveC(){busy.value=true;try{const x={name:ch.name,enabled:ch.enabled,config:{...ch.config}};if(cid.value)await api.updateNotificationChannel(cid.value,x);else await api.createNotificationChannel(x);await load();resetC();notify("渠道已保存","success")}catch(e){notify(e instanceof Error?e.message:String(e),"error")}finally{busy.value=false}}
async function deleteC(x:NotificationChannel){if(!confirm("删除渠道 "+x.name+"？"))return;try{await api.deleteNotificationChannel(x.id);await load();resetC()}catch(e){notify(e instanceof Error?e.message:String(e),"error")}}
async function testC(x:NotificationChannel){try{const r=await api.testNotificationChannel(x.id);notify(r.success?"测试通知已被接受":r.message,r.success?"success":"error")}catch(e){notify(e instanceof Error?e.message:String(e),"error")}}
function resetR(){rid.value="";Object.assign(rule,{name:"",enabled:true,eventType:"task.execution",phase:"finished",outcome:"failure",channelIds:[],subjectType:""})}function editR(x:NotificationRule){rid.value=x.id;Object.assign(rule,{name:x.name,enabled:x.enabled,eventType:x.eventType,phase:x.phase,outcome:x.outcome??"any",channelIds:[...x.channelIds],subjectType:x.subjectType??""})}
function setEvent(v:string){rule.eventType=v as NotificationRule["eventType"];if(!phases.value.includes(rule.phase))rule.phase=phases.value[0]??"finished";if(rule.outcome!=="any"&&!outcomes.value.includes(rule.outcome as never))rule.outcome="any"}
async function saveR(){busy.value=true;try{const x={...rule,subjectType:rule.subjectType.trim()||undefined};if(rid.value)await api.updateNotificationRule(rid.value,x);else await api.createNotificationRule(x);await load();resetR();notify("规则已保存","success")}catch(e){notify(e instanceof Error?e.message:String(e),"error")}finally{busy.value=false}}
async function deleteR(x:NotificationRule){if(!confirm("删除规则 "+x.name+"？"))return;try{await api.deleteNotificationRule(x.id);await load();resetR()}catch(e){notify(e instanceof Error?e.message:String(e),"error")}}
async function retry(id:string){try{await api.retryNotificationDelivery(id);await load()}catch(e){notify(e instanceof Error?e.message:String(e),"error")}}
onMounted(()=>void load());
</script>
<template><AdminLayout active="notifications" :title="t('nav.notifications')" :subtitle="t('notifications.subtitle')"><main class="page"><p class="intro">事件驱动通知：配置可复用渠道，再按事件、阶段、结果配置通知规则。业务事件不依赖 PAC 文件实现。</p><p v-if="loading">{{t("common.loading")}}</p><p v-else-if="error" class="error">{{error}} <button @click="load">重试</button></p><template v-else><nav class="tabs"><button @click="tab='channels'">渠道（{{channels.length}}）</button><button @click="tab='rules'">规则（{{rules.length}}）</button><button @click="tab='history'">事件与投递</button></nav>
<section v-if="tab==='channels'" class="columns"><div class="panel"><button @click="resetC">新增渠道</button><article v-for="x in channels" :key="x.id" class="item"><div><b>{{x.name}}</b><p>{{x.provider}} · {{x.enabled?'启用':'停用'}}</p><small>{{x.config.url}}</small></div><div><button @click="testC(x)">测试</button><button @click="editC(x)">编辑</button><button @click="deleteC(x)">删除</button></div></article></div><form class="panel form" @submit.prevent="saveC"><h2>{{cid?'编辑渠道':'新增渠道'}}</h2><label>名称<input v-model="ch.name" required/></label><label>类型<select v-model="ch.config.provider"><option value="dingtalk">钉钉</option><option value="custom">HTTP Webhook</option></select></label><label>URL<input v-model="ch.config.url" required/><small>已脱敏的 URL 不变时会保留原凭据。</small></label><template v-if="ch.config.provider==='dingtalk'"><label>加签密钥<input v-model="ch.config.dingTalkSecret" type="password" placeholder="留空保留原密钥"/></label><label>消息格式<select v-model="ch.config.dingTalkMessageType"><option value="text">文本</option><option value="markdown">Markdown</option></select></label><label>消息模板<textarea v-model="ch.config.messageTemplate" rows="4"/></label></template><template v-else><label>HTTP 方法<select v-model="ch.config.method"><option>POST</option><option>PUT</option><option>PATCH</option></select></label><label>请求头 JSON<textarea v-model="ch.config.headers" rows="3"/></label><label>请求体 JSON 模板<textarea v-model="ch.config.body" rows="5"/></label></template><label><input v-model="ch.enabled" type="checkbox"/>启用</label><footer><button type="button" @click="resetC">重置</button><button class="primary" :disabled="busy">保存渠道</button></footer></form></section>
<section v-else-if="tab==='rules'" class="columns"><div class="panel"><button @click="resetR">新增规则</button><article v-for="x in rules" :key="x.id" class="item"><div><b>{{x.name}}</b><p>{{evName(x.eventType)}} · {{phaseName(x.phase)}} · {{outcomeName(x.outcome)}}</p><small>{{x.channelIds.map(cn).join('、')}}</small></div><div><button @click="editR(x)">编辑</button><button @click="deleteR(x)">删除</button></div></article></div><form class="panel form" @submit.prevent="saveR"><h2>{{rid?'编辑规则':'新增规则'}}</h2><label>名称<input v-model="rule.name" required/></label><label>事件<select :value="rule.eventType" @change="setEvent(($event.target as HTMLSelectElement).value)"><option v-for="x in catalog" :key="x.type" :value="x.type">{{x.label}}</option></select></label><label>阶段<select v-model="rule.phase"><option v-for="x in phases" :key="x" :value="x">{{phaseName(x)}}</option></select></label><label>结果<select v-model="rule.outcome"><option value="any">不限制</option><option v-for="x in outcomes" :key="x" :value="x">{{outcomeName(x)}}</option></select><small>开始阶段通常没有最终结果。</small></label><label>对象类型（可选）<input v-model="rule.subjectType" placeholder="task"/></label><fieldset><legend>通知渠道</legend><label v-for="x in channels" :key="x.id"><input v-model="rule.channelIds" type="checkbox" :value="x.id" :disabled="!x.enabled"/> {{x.name}}</label></fieldset><label><input v-model="rule.enabled" type="checkbox"/>启用规则</label><footer><button type="button" @click="resetR">重置</button><button class="primary" :disabled="busy||!channels.length">保存规则</button></footer></form></section>
<section v-else class="panel"><h2>事件记录</h2><article v-for="x in events" :key="x.id" class="item"><div><b>{{evName(x.type)}} · {{phaseName(x.phase)}} · {{outcomeName(x.outcome)}}</b><p>{{x.summary}}</p><small>{{x.occurredAt}}</small></div></article><h2>投递记录</h2><article v-for="x in deliveries" :key="x.id" class="item"><div><b>{{cn(x.channelId)}} · {{x.status}}</b><p>{{x.lastError}}</p><small>{{x.updatedAt}} · 尝试 {{x.attemptCount}} 次</small></div><button v-if="x.status==='failed'" @click="retry(x.id)">重试</button></article></section></template><AppFooter/></main></AdminLayout></template>
<style scoped>
.page{display:grid;gap:16px;min-width:0}.intro,.panel{padding:18px;border:1px solid var(--line);border-radius:12px;background:var(--surface);font-size:12px}.tabs,.columns,.item,footer{display:flex;gap:10px;flex-wrap:wrap}.tabs button,.panel button{padding:8px 11px;border:1px solid var(--line);border-radius:7px;background:var(--surface);color:var(--text);font:inherit;font-size:11px;cursor:pointer}.columns{display:grid;grid-template-columns:minmax(0,1fr) minmax(300px,.9fr);align-items:start}.item{justify-content:space-between;padding:12px 0;border-top:1px solid var(--line)}.item>div:first-child{min-width:0}.item p,.item small,.form small{display:block;color:var(--muted);font-size:11px;overflow-wrap:anywhere}.form{display:grid;gap:12px}.form h2,.panel h2{margin:0;font-size:15px}.form label{display:grid;gap:6px;font-size:12px}.form input:not([type=checkbox]),.form select,.form textarea{box-sizing:border-box;width:100%;min-width:0;padding:9px;border:1px solid var(--line);border-radius:7px;background:var(--bg);color:var(--text);font:inherit}.form textarea{font-family:var(--font-mono)}.form input[type=checkbox]{accent-color:var(--accent)}fieldset{display:grid;gap:8px;border:1px solid var(--line);border-radius:8px}footer{justify-content:flex-end}.primary{background:var(--accent)!important;color:white!important}.error{color:var(--red)}@media(max-width:850px){.columns{grid-template-columns:1fr}.columns>.form{order:-1}}@media(max-width:600px){.item{flex-direction:column}}
</style>